/**
 * @name File path injection vulnerabilities
 * @description Detects potential file path injection where user input flows to file operations
 * @kind path-problem
 * @problem.severity error
 * @id py/file-path-injection
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FilePathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        // File open operations
        call = API::moduleImport("builtins").getMember("open").getACall() or
        call = API::moduleImport("os").getMember(["open", "fdopen"]).getACall() or
        call = API::moduleImport("io").getMember(["open", "FileIO"]).getACall() or
        // Path operations
        call = API::moduleImport("os.path").getMember(["join", "abspath", "realpath"]).getACall() or
        call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() or
        call = API::moduleImport("os").getMember(["remove", "unlink", "rename", "listdir"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module FilePathInjectionFlow = TaintTracking::Global<FilePathInjectionConfig>;
import FilePathInjectionFlow::PathGraph

from FilePathInjectionFlow::PathNode source, FilePathInjectionFlow::PathNode sink
where FilePathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File path injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerabilities
 * @description Detects potential path traversal vulnerabilities in file operations
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    // os.path operations
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs", "chdir", "listdir", "stat", "lstat", "access", "chmod", "chown", "rename", "replace", "link", "symlink"]).getACall() and
      sink = call.getArg(0)
    ) or
    // shutil operations  
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "copytree", "move", "rmtree", "chown", "which"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Pathlib operations
    exists(API::CallNode call |
      call = API::moduleImport("pathlib").getMember(["Path"]).getACall() and
      sink = call
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
